}

func (w *Writer) loop() {
	defer w.wg.Done()
	for entry := range w.ch {
		w.writeEntry(entry)
	}
}

func (w *Writer) writeEntry(entry Entry) {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.file == nil {
		return
	}

	// Check rotation before writing
	if fi, err := w.file.Stat(); err == nil && fi.Size() >= maxFileSize {
