	if err != nil {
		return
	}
	data = append(data, '\n')
	if _, err := w.file.Write(data); err != nil {
		// ignore or log
	}
}

func (w *Writer) rotateLocked() {
	if w.file != nil {
		w.file.Close()
	}
	// rename to .1 (overwrite)
	backup := w.path + ".1"
	os.Remove(backup)
	os.Rename(w.path, backup)
	w.openFile()
}

func (w *Writer) Close() {
	close(w.ch)
	w.wg.Wait()
	w.mu.Lock()
	if w.file != nil {
		w.file.Close()
		w.file = nil
	}
	w.mu.Unlock()
