package accesslog

import (
	"bufio"
	"encoding/json"
	"os"
)

// Stats holds aggregated access log statistics for one result type.
type Stats struct {
	Count         int   `json:"count"`
	AvgDurationMs int64 `json:"avg_duration_ms"`
	TotalBytesIn  int64 `json:"total_bytes_in"`
	TotalBytesOut int64 `json:"total_bytes_out"`
}

// StatsResult is the response shape for get_access_stats.
type StatsResult struct {
	TotalRequests int              `json:"total_requests"`
	ByResult      map[string]Stats `json:"by_result"`
}

// ReadEntries reads and parses log entries from the backup file plus the
// current log file, in chronological order. Invalid lines are skipped.
func ReadEntries(path string) []Entry {
	var entries []Entry
	entries = append(entries, readLogFile(path+".1")...)
	entries = append(entries, readLogFile(path)...)
	return entries
}

func readLogFile(path string) []Entry {
	f, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer f.Close()

	var entries []Entry
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var e Entry
		if err := json.Unmarshal(line, &e); err != nil {
			continue
		}
		entries = append(entries, e)
	}
	return entries
}

// GetAccessLog returns filtered log entries. Filters are applied first, then the
// last lastN entries are returned. If lastN is 0 or negative, all matching
// entries are returned.
func GetAccessLog(path, service, result string, lastN int, minDurationMs int64) []Entry {
	entries := ReadEntries(path)

	filtered := entries[:0]
	for _, e := range entries {
		if service != "" && e.Service != service {
			continue
		}
		if result != "" && e.Result != result {
			continue
		}
		if minDurationMs > 0 && e.DurationMs < minDurationMs {
			continue
		}
		filtered = append(filtered, e)
	}

	if lastN <= 0 {
		return filtered
	}
	if len(filtered) > lastN {
		return filtered[len(filtered)-lastN:]
	}
	return filtered
}

// Stats aggregates access log entries for the optional service filter.
func Stats(path, service string) StatsResult {
	entries := ReadEntries(path)

	type agg struct {
		count    int
		duration int64
		bytesIn  int64
		bytesOut int64
	}
	aggs := make(map[string]*agg)
	total := 0

	for _, e := range entries {
		if service != "" && e.Service != service {
			continue
		}
		a := aggs[e.Result]
		if a == nil {
			a = &agg{}
			aggs[e.Result] = a
		}
		a.count++
		a.duration += e.DurationMs
		a.bytesIn += e.BytesIn
		a.bytesOut += e.BytesOut
		total++
	}

	result := StatsResult{
		TotalRequests: total,
		ByResult:      make(map[string]Stats),
	}
	for name, a := range aggs {
		if a.count == 0 {
			continue
		}
		result.ByResult[name] = Stats{
			Count:         a.count,
			AvgDurationMs: a.duration / int64(a.count),
			TotalBytesIn:  a.bytesIn,
			TotalBytesOut: a.bytesOut,
		}
	}
	return result
}
