func (l *Logger) writeLine(e Entry) {
    b, err := json.Marshal(e)
    if err != nil {
        return
    }
    b = append(b, '\n')

    l.mu.Lock()
    defer l.mu.Unlock()

    if l.file == nil {
        if err := os.MkdirAll(filepath.Dir(l.path), 0755); err != nil {
            return
        }
        f, err := os.OpenFile(l.path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
        if err != nil {
            return
        }
        l.file = f
        if info, err := f.Stat(); err == nil {
            l.size = info.Size()
        }
    }

    if l.size > 0 && l.size+int64(len(b)) > maxFileSize {
        l.rotateLocked()
    }

    n, err := l.file.Write(b)
    if err != nil {
        l.size = 0
        if l.file != nil {
            l.file.Close()
            l.file = nil
        }
        return
    }
    l.size += int64(n)
}

func (l *Logger) rotateLocked() {
    if l.file != nil {
        l.file.Close()
        l.file = nil
    }
    os.Remove(l.path + ".1")
    if err := os.Rename(l.path, l.path+".1"); err != nil {
        f, err := os.OpenFile(l.path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
        if err == nil {
            l.file = f
            if info, err := f.Stat(); err == nil {
                l.size = info.Size()
            }
        }
        return
    }
    f, err := os.OpenFile(l.path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0644)
    if err != nil {
        l.size = 0
        return
    }
    l.file = f
    l.size = 0
}
